using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Windows.Forms;
using System.Drawing;
namespace Ara {
 public static class ConnectedTests {
  static void Assert(bool ok,string message){if(!ok)throw new Exception(message);}
  class Fake {
   public readonly string parent=Guid.NewGuid().ToString(),page=Guid.NewGuid().ToString();public int creates,patches;public bool responseLost;public List<Dictionary<string,object>> blocks=new List<Dictionary<string,object>>();
   public Dictionary<string,object> Call(string method,string path,object value){
    if(path=="pages/"+parent)return JsonMap.Obj("id",parent,"properties",JsonMap.Obj("title",JsonMap.Obj("type","title","title",new[]{JsonMap.Obj("text",JsonMap.Obj("content","보관함"))})));
    if(path=="search")return JsonMap.Obj("results",new[]{JsonMap.Obj("id",parent,"object","page","properties",JsonMap.Obj("title",JsonMap.Obj("type","title","title",new[]{JsonMap.Obj("plain_text","보관함")}))) });
    if(path=="pages"&&method=="POST"){creates++;blocks=JsonMap.Items(JsonMap.Map(value),"children").Select(x=>JsonMap.Read(JsonMap.Write(x))).ToList();foreach(var b in blocks)b["id"]=Guid.NewGuid().ToString();if(responseLost){responseLost=false;throw new IOException("lost response");}return JsonMap.Obj("id",page,"url","https://www.notion.so/"+page);}
    if(path.StartsWith("blocks/"+parent+"/children"))return JsonMap.Obj("results",creates==0?new object[0]:new object[]{JsonMap.Obj("id",page,"type","child_page","child_page",JsonMap.Obj("title","2026-10-15 · 하루 기록"))});
    if(path.StartsWith("blocks/"+page+"/children"))return JsonMap.Obj("results",blocks.ToArray());
    if(path=="pages/"+page)return JsonMap.Obj("id",page,"properties",JsonMap.Obj("title",JsonMap.Obj("type","title","title",new[]{JsonMap.Obj("plain_text","하루 기록")})));
    var block=blocks.Find(x=>path=="blocks/"+JsonMap.Str(x,"id"));if(block!=null){if(method=="PATCH"){patches++;foreach(var pair in JsonMap.Map(value))block[pair.Key]=pair.Value;}return block;}
    throw new Exception("Unexpected "+method+" "+path);
   }
  }
  static State Sample(){var s=State.New();CategoryCatalog.Ensure(s);var d=s.GetDay(new DateTime(2026,10,15));d.Wake=d.Wake.Date.AddHours(20);GridEngine.Ensure(s,d);d.Records.Add(new CellBlock{Id="sample",Start=d.Wake.Date.AddDays(1).AddHours(3),Count=3,Category="학습",Name="기록",Score=4,Satisfaction=5});d.Note="메모";return s;}
  static NotionService Service(string dir,string name,Fake fake){var service=new NotionService(Path.Combine(dir,name,"state.json"));service.Transport=fake.Call;service.Destination(fake.parent,"page",false);return service;}
  public static void Run(Action<string,Action> check,string dir){
   check("connected: waking date export keeps next-day timestamps and weighted metrics",()=>{var s=Sample();var before=JsonMap.Write(s);var e=DailyExport.Create(s,"2026-10-15");Assert(e.wake_date=="2026-10-15"&&JsonMap.Str(JsonMap.Map(e.actual[0]),"start_at")=="2026-10-16T03:00:00+09:00","waking date");Assert(Convert.ToDecimal(JsonMap.Map(e.summary)["focus_total"])==12&&Math.Abs(Convert.ToDecimal(JsonMap.Map(e.summary)["satisfaction_time_weighted"])-(2m+9m/99))<.000001m,"metrics");Assert(JsonMap.Write(s)==before,"export read only");});
   check("connected: page IDs reject arbitrary URLs and parse Notion links",()=>{string id=Guid.NewGuid().ToString();Assert(NotionService.Id("https://www.notion.so/title-"+id.Replace("-","")+"?pvs=4")==id,"URL id");bool rejected=false;try{NotionService.Id("https://example.com/no-id");}catch(InvalidDataException){rejected=true;}Assert(rejected,"bad ID");});
   check("connected: Notion secret is DPAPI encrypted and absent from status",()=>{var service=new NotionService(Path.Combine(dir,"encrypted","state.json"));const string secret="ntn_this_is_only_a_test_credential";service.Connect(secret);string data=Encoding.UTF8.GetString(File.ReadAllBytes(Path.Combine(dir,"encrypted","notion-connection.bin")));Assert(!data.Contains(secret)&&!JsonMap.Write(service.Status()).Contains(secret),"no plaintext");});
   check("connected: daily save reuses page and preserves personal blocks",()=>{var fake=new Fake();var service=Service(dir,"notion-save",fake);service.Publish(Sample(),"2026-10-15","첫 초안");var personal=JsonMap.Map(NotionService.Block("paragraph","내가 직접 쓴 내용"));personal["id"]=Guid.NewGuid().ToString();fake.blocks.Add(personal);service.Publish(Sample(),"2026-10-15","수정 초안");Assert(fake.creates==1&&fake.patches==2&&fake.blocks.Last()==personal,"upsert/personal");});
   check("connected: remote diary edit blocks blind overwrite and can be read",()=>{var fake=new Fake();var service=Service(dir,"notion-conflict",fake);service.Publish(Sample(),"2026-10-15","첫 초안");var diary=fake.blocks[3];diary["paragraph"]=JsonMap.Child(JsonMap.Map(NotionService.Block("paragraph","노션 수정")),"paragraph");bool rejected=false;try{service.Publish(Sample(),"2026-10-15","예전 초안");}catch(InvalidOperationException){rejected=true;}Assert(rejected&&fake.patches==0,"remote edit preserved");var pulled=JsonMap.Map(service.ReadDaily("2026-10-15"));Assert(JsonMap.Str(pulled,"draft")=="노션 수정","pull");service.Publish(Sample(),"2026-10-15","노션 수정");Assert(fake.creates==1,"read-preserved retry");});
   check("connected: lost create response is reconciled from parent before retry",()=>{var fake=new Fake{responseLost=true};var service=Service(dir,"notion-lost",fake);try{service.Publish(Sample(),"2026-10-15","초안");}catch(IOException){}service.Publish(Sample(),"2026-10-15","초안");Assert(fake.creates==1,"not duplicated");});
   check("connected: source selection resolves actual title property",()=>{var service=new NotionService(Path.Combine(dir,"source","state.json"));string id=Guid.NewGuid().ToString();service.Transport=(m,p,b)=>JsonMap.Obj("id",id,"title",new[]{JsonMap.Obj("plain_text","일기 DB")},"properties",JsonMap.Obj("내 날짜 제목",JsonMap.Obj("type","title")));var target=service.Resolve(id,"data_source");Assert(target.titleProperty=="내 날짜 제목"&&target.title=="일기 DB","schema discovery");});
   check("connected: Notion and update routes require paired authentication",()=>{string folder=Path.Combine(dir,"connected-auth");Directory.CreateDirectory(folder);using(var form=new MainForm(new Store(Path.Combine(folder,"state.json")),Sample(),true))using(var server=new MobileServer(form,18765)){foreach(string path in new[]{"/api/update","/api/ui-bundle","/api/app-package","/api/notion"}){var response=server.Dispatch(path.EndsWith("notion")?"POST":"GET",path,new Dictionary<string,string>{{"host","127.0.0.1:18765"}},Encoding.UTF8.GetBytes("{}"),"127.0.0.1");Assert(response.status==401,"auth "+path);}form.Quit();}});
   check("connected: Notion window renders without credentials or network access",()=>{string folder=Path.Combine(dir,"notion-ui");Directory.CreateDirectory(folder);using(var form=new MainForm(new Store(Path.Combine(folder,"state.json")),Sample(),true))using(var dialog=new NotionWindow(form)){dialog.Show();Application.DoEvents();using(var image=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(image,new Rectangle(Point.Empty,dialog.Size));image.Save(Path.Combine(dir,"notion-settings-smoke.png"));}dialog.Close();form.Quit();}});
   check("connected: search results use human titles and reference reads preserve state",()=>{var fake=new Fake();var service=Service(dir,"notion-read",fake);var s=Sample();service.Publish(s,"2026-10-15","초안");var before=JsonMap.Write(s);Assert(service.Search("")[0].title=="보관함","title");var read=JsonMap.Map(service.ReadReference(fake.page,"page"));Assert(JsonMap.Str(read,"text").Contains("초안")&&JsonMap.Write(s)==before,"read only");Assert(!File.Exists(Path.Combine(dir,"notion-read","notion-reference.json")),"unselected read must not become AI reference");service.Destination(fake.page,"page",true);service.ReadReference(fake.page,"page");Assert(File.Exists(Path.Combine(dir,"notion-read","notion-reference.json")),"selected reference cached");service.SetModel("local-test-model");Assert(service.Load().model=="local-test-model"&&service.Load().links.Count==1,"model change preserves links");});
  }
 }
}
